    t = NullTranslations()
    for i in range(depth):
        t.add_fallback(NullTranslations())
    for message in ["", "hello", "é中😀", "a\nb", "%(name)s"]:
        print(depth, t.gettext(message), t.pgettext("ctx", message), t.charset(), len(t.info()))
for domain in ["messages", "app", "unicode-é"]:
